  mail: { title: '배번호 서류 등기 발송 안내드립니다', text: function (m) { return '서류에 서명 · 도장 후 등기로 보내 주세요. (' + m.zip + ') ' + m.addr; } },
  final: { title: '배번호 최종제출 서류 안내드립니다', text: function () { return '허가가 났습니다. 화물운송 허가증 · 자동차등록증 · 화물운송 자격증 3종을 앱에서 올려 주세요.'; } }
