/** 파일 한 개를 기사 서류 폴더에 넣고 주소를 돌려준다 */
function bibSaveDoc_(app, d, key, file) {
  const def = BIB_FINAL.filter(function (f) { return f[0] === key; })[0];
  if (!def) fail_('알 수 없는 서류입니다.');
  if (!file || !file.data) fail_('파일을 골라 주세요.');
  const mime = /^(image\/(jpeg|png)|application\/pdf)$/.test(String(file.mime)) ? String(file.mime) : '';
  if (!mime) fail_('사진(JPG · PNG) 또는 PDF 만 올릴 수 있습니다.');
  if (String(file.data).length > 11000000) fail_('파일이 너무 큽니다. 8MB 보다 작은 파일로 올려 주세요.');
  let folder = folderFromUrl_(d.docFolder);
  if (!folder) {
    folder = DriveApp.getFolderById(props_().DOCS_FOLDER_ID).createFolder((d.name || '기사') + '_' + (d.loginId || d.id) + '_' + d.id);
    writeFields_(SH.DRIVERS, d._row, { docFolder: folder.getUrl() }); forgetDriver_(d);
  }
  const ext = mime === 'application/pdf' ? 'pdf' : mime === 'image/png' ? 'png' : 'jpg';
  const blob = Utilities.newBlob(Utilities.base64Decode(file.data), mime, (d.name || d.id) + '_배번호_' + def[2] + '_' + Utilities.formatDate(new Date(), CFG.TZ, 'yyyyMMdd_HHmmss') + '.' + ext);
  const url = folder.createFile(blob).getUrl();
  const f = { updatedAt: nowText_() }; f[def[1]] = url;
  writeFields_(SH.BIB, app._row, f);
  return def;
}
/** 관리자: 최종 서류를 대신 올리기(카톡으로 받은 경우) · 지우기(file 없이) */
function adm_bibDocUp(token, id, key, file) {
  return run_(function () {
    const a = requireAdmin_(token);
    const lock = scriptLock_(); lock.waitLock(20000);
    try {
      const app = bibById_(id);
      if (!app) fail_('신청서를 찾을 수 없습니다. 새로고침해 주세요.');
      if (app.status !== BST.FINAL) fail_('최종서류 단계의 신청서만 고칠 수 있습니다.');
      const d = driverById_(app.driverId); if (!d) fail_('기사 정보를 찾을 수 없습니다.');
      const def = BIB_FINAL.filter(function (f) { return f[0] === key; })[0];
      if (!def) fail_('알 수 없는 서류입니다.');
      if (file && file.data) bibSaveDoc_(app, d, key, file);
      else { const f = { updatedAt: nowText_() }; f[def[1]] = ''; writeFields_(SH.BIB, app._row, f); }
      logAdmin_(a, '배번호 최종 서류', app.name + ' (' + app.driverId + ')', def[2] + (file && file.data ? ' 올림' : ' 지움'));
      return Object.assign({ ok: true }, bibDetail_(readObj_(SH.BIB, app._row)));
    } finally { lock.releaseLock(); }
  });
}
/** 관리자: 최종 서류 한 개 열기 (보기 · 내려받기) */
function adm_bibDoc(token, id, key) {
  return run_(function () {
    const a = requireAdmin_(token);
    const app = bibById_(id);
    if (!app) fail_('신청서를 찾을 수 없습니다.');
    const def = BIB_FINAL.filter(function (f) { return f[0] === key; })[0];
    if (!def) fail_('알 수 없는 서류입니다.');
    const url = str_(app[def[1]]);
    const m = url.match(/\/d\/([A-Za-z0-9_-]{10,})/) || url.match(/[?&]id=([A-Za-z0-9_-]{10,})/);
    if (!m) fail_('올라온 ' + def[2] + ' 파일이 없습니다.');
    let file;
    try { file = DriveApp.getFileById(m[1]); } catch (e) { fail_('파일을 열 수 없습니다.'); }
    if (file.getSize() > 15 * 1024 * 1024) fail_('파일이 너무 큽니다.');
    const blob = file.getBlob();
    logAdmin_(a, '서류 열람', app.name + ' (' + app.driverId + ')', '배번호 ' + def[2]);
    return { ok: true, mime: blob.getContentType(), data: Utilities.base64Encode(blob.getBytes()), name: file.getName(), label: def[2] };
  });
}
/** 기사앱: 내 배번호 진행 — 알릴 것이 있을 때만 항목이 온다 (등기 주소 안내를 받았거나 · 최종 서류를 내야 하거나) */
function api_bibMine(token) {
  return run_(function () {
    const u = pmUser_(token);
    const m = bibMailInfo_();
    const items = readAll_(SH.BIB).filter(function (o) { return o.id && String(o.driverId) === u.id; }).map(function (o) {
      if (o.status === BST.FINAL) return { id: o.id, step: 'final', plateNo: o.plateNo, docs: bibFinalDocs_(o), at: o.finalNotiAt || o.approvedAt };
      if ((o.status === BST.PRINTED || o.status === BST.SUBMITTED) && o.mailNotiAt) return { id: o.id, step: 'mail', zip: m.zip, addr: m.addr, at: o.mailNotiAt, sent: o.status === BST.SUBMITTED };
      return null;
    }).filter(Boolean);
    return { ok: true, items: items, labels: BIB_FINAL.map(function (f) { return [f[0], f[2]]; }) };
  });
}
/** 기사앱: 최종 서류 한 개 올리기 (본인 신청서 · 최종서류 단계만) */
function api_bibDocUp(token, id, key, file) {
  return run_(function () {
    const u = pmUser_(token);
    const lock = scriptLock_(); lock.waitLock(20000);
    try {
      const app = bibById_(id);
      if (!app || String(app.driverId) !== u.id) fail_('신청서를 찾을 수 없습니다.');
      if (app.status !== BST.FINAL) fail_('지금은 서류를 올릴 수 없습니다. 사무실에 문의해 주세요.');
      const d = driverById_(u.id); if (!d) fail_('기사 정보를 찾을 수 없습니다.');
      bibSaveDoc_(app, d, key, file);
      const now = readObj_(SH.BIB, app._row);
      return { ok: true, docs: bibFinalDocs_(now), all: bibFinalAll_(now) };
    } finally { lock.releaseLock(); }
  });
}

