  out.address = req_(f.address, '주소', 200);
  out.phone = fmtPhone_(f.phone);
  const biz = digits_(req_(f.bizNo, '사업자등록번호', 20));
  if (biz.length !== 10) fail_('사업자등록번호 10자리를 입력해 주세요.');
  out.bizNo = biz.replace(/(\d{3})(\d{2})(\d{5})/, '$1-$2-$3');
