  s = s.replace(/(\d+[A-Za-z]+)\(([^)]*)\)/g, function (m0, rt, ro) {
    const rr = normRot_(ro); if (!rr.length) return m0;
    issExpand_(rt).forEach(function (x) { per[x] = rr; }); return rt;
  });
  let rot = null;
  const mR = s.match(/\(([^)]*)\)/);
  if (mR) { const rr = normRot_(mR[1]); if (rr.length) rot = rr; s = s.replace(/\([^)]*\)/g, ' '); }
