  let txt;
  if (Object.keys(ks).length === 1) {
    const k = groups[0].k;
    txt = groups.map(function (g) { return g.n + g.c; }).join(',') + (k !== all ? ' (' + k + ')' : '');
  } else txt = groups.map(function (g) { return g.n + g.c + (g.k !== all ? '(' + g.k + ')' : ''); }).join(',');
