function issNewId_() { return 'I' + Utilities.formatDate(new Date(), CFG.TZ, 'yyMMddHHmmss') + Math.floor(Math.random() * 900 + 100); }
/** 이슈 한 줄 쓰기 (x.row 가 있으면 그 줄, 없으면 맨 아래 · 잠금 안에서) */
