  m.prices.forEach(function (p) { if (money(p.p2) > 0 || money(p.p3) > 0) priced[p.campId + '|' + p.num] = 1; });
  // ① 기본노선의 숫자가 그 캠프 노선관리(사용)에 없음 (노선을 하나도 등록하지 않은 캠프는 건너뜀)
  const a1 = [];
