      if (q && (str_(j.area) + str_(j.camp) + str_(j.route)).replace(/\s+/g, '').toLowerCase().indexOf(q) < 0) return false;
      if (f.onlyAvail && pmCanApply_(j, u.id, d.apps, today)) return false;
