  if (!s || s === '-' || s === '퇴사') return { v: '', kind: 'skip' };
  if (/^계획된\s*휴무$/.test(s)) return { v: '추가휴무', kind: 'conv' };
  if (['출근', '휴무', '고정휴무', '추가휴무', '병가', '휴가', '미입차', '노쇼', '용차'].indexOf(s) >= 0) return { v: s, kind: 'same' };
