    if (/^(?:[가-힣]+\s?\d+\s+)?\d{3,4}[A-Za-z]/.test(rest)) { const r2 = schLegacyConv_(rest, base, ownCamp); return r2.kind === 'need' || r2.kind === 'skip' ? { v: '', kind: 'need', why: '품앗이 노선을 읽을 수 없습니다' } : { v: r2.v, kind: 'conv' }; }
