      // 같은 날 · 같은 노선은 한 줄만: 있던 줄은 지우고(아래에서부터) 새로 적는다
      schRmRead_().filter(function (x) { return want[x.date + '|' + x.camp + '|' + x.unit]; }).map(function (x) { return x.row; }).sort(function (p, q) { return q - p; }).forEach(function (r) { sh.deleteRow(r); });
