    const target = stlNum_(a.target), unit = stlNum_(a.unit) || 10000;
    if (!from || !to || !target || !S[from]) return;
    const netAt = function (x) { return fin(from, (extraAdj[from] || []).concat([{ item: '매출 분할 이전', amt: x, auto: true }])).net; };
