  Object.keys(S).forEach(function (id) { if (!S[id].sched) S[id].sched = X.groups[id] ? stlGroupSched_(ctx, X.groups[id], sched, P, S[id].cidDays || {}) : { days: 0, byCid: [], src: '', cells: {} }; });
