    const out = { ok: true, months: months, extraTo: extraTo || '', company: co, dedNames: dedNames, summary: [], invoices: [], pays: [], staff: [], ins: [], costs: [], deposits: [], advances: [], losses: [], files: [], noBiz: [] };
